  color: var(--color-dark);
  font-size: var(--font-size-xs);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: var(--space-md);
  border-radius: var(--radius-sm);
}

.hero h1 {
  color: var(--color-text-inverse);
  margin-bottom: var(--space-md);
}

.hero p {
  font-size: var(--font-size-lg);
  color: rgba(255,255,255,0.8);
  margin-bottom: var(--space-lg);
}

/* Cards */
.card {
  background-color: var(--color-bg-white);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card-image {
  position: relative;
  height: 200px;
  background-color: var(--color-neutral);
  overflow: hidden;
}

.card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.card-content {
  padding: var(--space-lg);
}

.card-tag {
  display: inline-block;
  padding: var(--space-xs) var(--space-sm);
  background-color: var(--color-bg-light);
  color: var(--color-primary);
  font-size: var(--font-size-xs);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: var(--radius-sm);
  margin-bottom: var(--space-sm);
}

.card h3 {
  font-size: var(--font-size-xl);
  margin-bottom: var(--space-sm);
}

.card p {
  font-size: var(--font-size-sm);
  color: var(--color-text-light);
}

.card-meta {
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  margin-top: var(--space-sm);
}

/* Announcement Banner */
.announcement-banner {
  background: linear-gradient(90deg, var(--color-accent), #D4AF50);
  padding: var(--space-md) 0;
  text-align: center;
}

.announcement-banner p {
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-dark);
  margin-bottom: 0;
}

.announcement-banner .btn {
  margin-left: var(--space-md);
  background-color: var(--color-dark);
  color: var(--color-text-inverse);
  font-size: var(--font-size-xs);
  padding: var(--space-xs) var(--space-md);
}

.announcement-banner .btn:hover {
  background-color: var(--color-primary);
}

/* About Statement */
.about-statement {
  background-color: var(--color-primary);
  color: var(--color-text-inverse);
  text-align: center;
}

.about-statement h2 {
  color: var(--color-text-inverse);
  font-size: var(--font-size-3xl);
  max-width: 900px;
  margin: 0 auto var(--space-md);
}

.about-statement p {
  font-size: var(--font-size-lg);
  opacity: 0.9;
  max-width: 700px;
  margin: 0 auto var(--space-lg);
}

/* What We Do Tabs */
.what-we-do {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: var(--space-xl);
  align-items: start;
}

.what-we-do-tabs {
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--color-neutral);
  padding-right: var(--space-xl);
}

.what-we-do-tab {
  padding: var(--space-md);
  text-align: left;
  font-size: var(--font-size-base);
  font-weight: 500;
  color: var(--color-text-light);
  border-left: 3px solid transparent;
  transition: all var(--transition-fast);
  cursor: pointer;
}

.what-we-do-tab:hover {
  color: var(--color-text);
}

.what-we-do-tab.active {
  color: var(--color-primary);
  border-left-color: var(--color-accent);
  background-color: var(--color-bg-light);
}

.what-we-do-content {
  padding: var(--space-lg);
  min-height: 400px;
}

.what-we-do-panel {
  display: none;
}

.what-we-do-panel.active {
  display: block;
  animation: fadeIn var(--transition-base);
}

.what-we-do-panel h3 {
  font-size: var(--font-size-2xl);
  margin-bottom: var(--space-md);
  color: var(--color-primary);
}

.what-we-do-panel p {
  font-size: var(--font-size-lg);
  color: var(--color-text-light);
  margin-bottom: var(--space-lg);
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Services Grid */
.services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

.service-card {
  background-color: var(--color-bg-white);
  padding: var(--space-xl);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-neutral);
  transition: all var(--transition-base);
}

.service-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
}

.service-card h3 {
  font-size: var(--font-size-xl);
  margin-bottom: var(--space-sm);
  color: var(--color-primary);
}

.service-card p {
  font-size: var(--font-size-sm);
  color: var(--color-text-light);
  margin-bottom: var(--space-md);
}

/* Capabilities Grid */
.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

.capability-card {
  background-color: var(--color-bg-white);
  padding: var(--space-lg);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-neutral);
  transition: all var(--transition-base);
}

.capability-card:hover {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-sm);
}

.capability-card h4 {
  font-size: var(--font-size-lg);
  color: var(--color-primary);
  margin-bottom: var(--space-sm);
}

.capability-card p {
  font-size: var(--font-size-sm);
  color: var(--color-text-light);
  margin-bottom: var(--space-md);
}

/* Newsletter Section */
.newsletter {
  background: linear-gradient(135deg, var(--color-secondary), var(--color-primary-dark));
  color: var(--color-text-inverse);
  text-align: center;
}

.newsletter h2 {
  color: var(--color-text-inverse);
  margin-bottom: var(--space-sm);
}

.newsletter p {
  font-size: var(--font-size-lg);
  opacity: 0.8;
  max-width: 500px;
  margin: 0 auto var(--space-lg);
}

.newsletter-form {
  display: flex;
  gap: var(--space-sm);
  max-width: 480px;
  margin: 0 auto;
}

.newsletter-form input {
  flex: 1;
  padding: var(--space-sm) var(--space-md);
  border: none;
  border-radius: var(--radius-sm);
  font-size: var(--font-size-sm);
}

.newsletter-form button {
  padding: var(--space-sm) var(--space-lg);
  background-color: var(--color-accent);
  color: var(--color-dark);
  font-weight: 600;
  border-radius: var(--radius-sm);
  transition: background-color var(--transition-fast);
}

.newsletter-form button:hover {
  background-color: var(--color-accent-hover);
}

/* Commitment Pills */
.commitment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-lg);
}

.commitment-card {
  background-color: var(--color-bg-white);
  padding: var(--space-xl);
  border-radius: var(--radius-md);
  text-align: center;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
}

.commitment-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.commitment-icon {
  width: 64px;
  height: 64px;
  margin: 0 auto var(--space-md);
  background-color: var(--color-bg-light);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-2xl);
}

.commitment-card h4 {
  font-size: var(--font-size-lg);
  margin-bottom: var(--space-sm);
  color: var(--color-primary);
}

.commitment-card p {
  font-size: var(--font-size-sm);
  color: var(--color-text-light);
}

/* Partners Carousel */
.partners-section {
  overflow: hidden;
}

.partners-track {
  display: flex;
  gap: var(--space-lg);
  transition: transform var(--transition-slow);
}

.partner-card {
  flex: 0 0 300px;
  background-color: var(--color-bg-white);
  padding: var(--space-xl);
  border-radius: var(--radius-md);
  text-align: center;
  border: 1px solid var(--color-neutral);
}

.partner-card h4 {
  color: var(--color-primary);
  margin-bottom: var(--space-sm);
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: var(--space-sm);
  margin-top: var(--space-lg);
}

.carousel-controls button {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background-color: var(--color-bg-white);
  border: 1px solid var(--color-neutral);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
  font-size: var(--font-size-lg);
}

.carousel-controls button:hover {
  background-color: var(--color-primary);
  color: var(--color-text-inverse);
  border-color: var(--color-primary);
}

/* CTA Section */
.cta-section {
  background-color: var(--color-bg-light);
  text-align: center;
}

.cta-section h2 {
  margin-bottom: var(--space-md);
}

.cta-section p {
  color: var(--color-text-light);
  max-width: 600px;
  margin: 0 auto var(--space-lg);
}

/* Footer */
.footer {
  background-color: var(--color-dark);
  color: var(--color-text-inverse);
  padding: var(--space-3xl) 0 var(--space-lg);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: var(--space-xl);
  margin-bottom: var(--space-2xl);
}

.footer-brand h3 {
  font-size: var(--font-size-xl);
  margin-bottom: var(--space-sm);
  color: var(--color-text-inverse);
}

.footer-brand p {
  color: rgba(255,255,255,0.6);
  font-size: var(--font-size-sm);
  max-width: 280px;
}

.footer-column h4 {
  font-size: var(--font-size-sm);
  font-weight: 600;
  color: var(--color-text-inverse);
  margin-bottom: var(--space-md);
}

.footer-column ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.footer-column a {
  color: rgba(255,255,255,0.6);
  font-size: var(--font-size-sm);
  transition: color var(--transition-fast);
}

.footer-column a:hover {
  color: var(--color-accent);
}

.footer-bottom {
  padding-top: var(--space-lg);
  border-top: 1px solid rgba(255,255,255,0.1);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer-bottom p {
  color: rgba(255,255,255,0.4);
  font-size: var(--font-size-xs);
  margin: 0;
}

.footer-legal {
  display: flex;
  gap: var(--space-lg);
}

.footer-legal a {
  color: rgba(255,255,255,0.4);
  font-size: var(--font-size-xs);
}

.footer-legal a:hover {
  color: var(--color-text-inverse);
}

/* Page-specific hero */
.page-hero {
  position: relative;
  min-height: 400px;
  display: flex;
  align-items: center;
  padding-top: 72px;
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-secondary) 100%);
}

.page-hero-content {
  position: relative;
  z-index: 1;
  max-width: 600px;
}

.page-hero h1 {
  color: var(--color-text-inverse);
  margin-bottom: var(--space-md);
}

.page-hero p {
  font-size: var(--font-size-lg);
  color: rgba(255,255,255,0.8);
}

.breadcrumb {
  display: flex;
  gap: var(--space-sm);
  font-size: var(--font-size-sm);
  margin-bottom: var(--space-md);
}

.breadcrumb a {
  color: rgba(255,255,255,0.6);
}

.breadcrumb a:hover {
  color: var(--color-accent);
}

.breadcrumb span {
  color: rgba(255,255,255,0.4);
}

/* Featured Topics Sidebar */
.featured-topics {
  background-color: var(--color-bg-light);
  padding: var(--space-lg);
  border-radius: var(--radius-md);
}

.featured-topics h4 {
  font-size: var(--font-size-sm);
  font-weight: 600;
  color: var(--color-primary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-md);
}

.featured-topics ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.featured-topics a {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-size: var(--font-size-sm);
  color: var(--color-text);
  padding: var(--space-sm);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.featured-topics a:hover {
  background-color: var(--color-bg-white);
  color: var(--color-primary);
}

.featured-topics a::before {
  content: '→';
  color: var(--color-accent);
}

/* Intro Statement */
.intro-statement {
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}

.intro-statement h2 {
  margin-bottom: var(--space-md);
}

.intro-statement p {
  font-size: var(--font-size-lg);
  color: var(--color-text-light);
}

/* Related Services */
.related-services {
  background-color: var(--color-bg-light);
  padding: var(--space-2xl) 0;
}

.related-services h3 {
  text-align: center;
  margin-bottom: var(--space-xl);
}

.related-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

.related-card {
  background-color: var(--color-bg-white);
  padding: var(--space-lg);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-neutral);
  transition: all var(--transition-base);
}

.related-card:hover {
  border-color: var(--color-accent);
}

.related-card span {
  display: block;
  font-size: var(--font-size-xs);
  color: var(--color-accent);
  text-transform: uppercase;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.related-card h4 {
  color: var(--color-primary);
  margin-bottom: var(--space-sm);
}

/* Testimonial */
.testimonial {
  background-color: var(--color-primary);
  color: var(--color-text-inverse);
  text-align: center;
  padding: var(--space-3xl) 0;
}

.testimonial blockquote {
  font-size: var(--font-size-2xl);
  font-style: italic;
  max-width: 800px;
  margin: 0 auto var(--space-lg);
  line-height: 1.5;
}

.testimonial cite {
  font-size: var(--font-size-sm);
  font-style: normal;
  opacity: 0.8;
}

/* Property Types CTA */
.property-types {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-md);
}

.property-type {
  background-color: var(--color-bg-white);
  padding: var(--space-lg);
  border-radius: var(--radius-md);
  text-align: center;
  border: 1px solid var(--color-neutral);
  transition: all var(--transition-base);
}

.property-type:hover {
  border-color: var(--color-primary);
  transform: translateY(-2px);
}

.property-type span {
  display: block;
  font-size: var(--font-size-2xl);
  margin-bottom: var(--space-sm);
}

.property-type strong {
  display: block;
  font-size: var(--font-size-sm);
  color: var(--color-primary);
}

/* Responsive */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
  .services-grid { grid-template-columns: repeat(2, 1fr); }
  .capabilities-grid { grid-template-columns: repeat(2, 1fr); }
  .commitment-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .what-we-do { grid-template-columns: 1fr; }
  .what-we-do-tabs { flex-direction: row; border-right: none; border-bottom: 1px solid var(--color-neutral); padding-right: 0; padding-bottom: var(--space-md); overflow-x: auto; }
  .what-we-do-tab { border-left: none; border-bottom: 3px solid transparent; white-space: nowrap; }
  .what-we-do-tab.active { border-left-color: transparent; border-bottom-color: var(--color-accent); }
  .property-types { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 768px) {
  :root {
    --font-size-5xl: 2.5rem;
    --font-size-4xl: 2rem;
    --font-size-3xl: 1.75rem;
  }

  .nav-list { display: none; }
  .mobile-menu-toggle { display: flex; }

  .hero { min-height: 500px; }
  .hero-content { padding: 0 var(--space-md); }

  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .services-grid { grid-template-columns: 1fr; }
  .capabilities-grid { grid-template-columns: 1fr; }
  .commitment-grid { grid-template-columns: 1fr; }
  .related-grid { grid-template-columns: 1fr; }
  .property-types { grid-template-columns: repeat(2, 1fr); }

  .newsletter-form { flex-direction: column; }
