  .partners-track { flex-wrap: wrap; justify-content: center; }
  .partner-card { flex: 0 0 calc(50% - var(--space-md)); }
}

/* Utility */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
